import React, { useState, useEffect } from 'react';
import './CategoryGrid.css';

const BASE = process.env.PUBLIC_URL || "";

// بيانات الأقسام بالصور والمنتجات (صور صافية بدون نصوص على الكارت)
const categoryData = {
  scrubs: {
    titleAr: 'معرض الإسكرابات الطبية',
    titleEn: 'Medical Scrubs Gallery',
    items: [
      { id: 1, titleAr: 'إسكراب نيون أزرق - رجال', titleEn: 'Neon Blue Scrub - Men', src: `${BASE}/1__1_-removebg-preview.png` },
      { id: 2, titleAr: 'إسكراب طبي كحلي - حريمي', titleEn: 'Navy Medical Scrub - Women', src: `${BASE}/1__3_-removebg-preview.png` },
      { id: 3, titleAr: 'إسكراب رمادي مريح', titleEn: 'Comfortable Grey Scrub', src: `${BASE}/McGuff_Medical_Products_IV_Tubing-removebg-preview.png` },
      { id: 4, titleAr: 'إسكراب بريميوم خاص', titleEn: 'Special Premium Scrub', src: `${BASE}/Masked Doctor in White Coat.png` },
      { id: 5, titleAr: 'إسكراب بريميوم خاص', titleEn: 'Special Premium Scrub', src: `${BASE}/1__5_-removebg-preview.png` },
      // { id: 6, titleAr: 'إسكراب بريميوم خاص', titleEn: 'Special Premium Scrub', src: `${BASE}/download__2_-removebg-preview.png` },
    ]
  },
  coats: {
    titleAr: 'معرض البالطوهات البيضاء',
    titleEn: 'White Lab Coats Gallery',
    items: [
      { id: 1, titleAr: 'بالطو أبيض طويل - كلاسيك', titleEn: 'Classic Long White Lab Coat', src: 'https://images.unsplash.com/photo-1622253692010-333f2da6031d?q=80&w=800' },
      { id: 2, titleAr: 'بالطو طبي مودرن قصير', titleEn: 'Modern Short Medical Lab Coat', src: 'https://images.unsplash.com/photo-1582750433449-648ed127bb54?q=80&w=800' },
    ]
  },
  stethoscopes: {
    titleAr: 'معرض أدوات التشخيص والسماعات',
    titleEn: 'Diagnostic Tools & Stethoscopes Gallery',
    items: [
      { id: 1, titleAr: 'سماعة طبيب نيون بروفيشينال', titleEn: 'Professional Neon Stethoscope', src: 'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?q=80&w=800' },
      { id: 2, titleAr: 'سماعة قلب عالية الحساسية', titleEn: 'High-Sensitivity Cardiology Stethoscope', src: 'https://images.unsplash.com/photo-1584515979956-d9f6e5d09982?q=80&w=800' },
    ]
  },
  'masks-protection': {
    titleAr: 'معرض التعقيم والحماية',
    titleEn: 'Sterilization & Protection Gallery',
    items: [
      { id: 1, titleAr: 'عبوة كمامات ثلاثية الطبقات (50 قطعة)', titleEn: 'Triple-Layer Face Mask Box (50 pcs)', src: 'https://images.unsplash.com/photo-1583947215259-38e31be8751f?q=80&w=800' },
      { id: 2, titleAr: 'واقي وجه شفاف معقم', titleEn: 'Sterile Clear Face Shield', src: 'https://images.unsplash.com/photo-1584634731339-252c581abfc5?q=80&w=800' },
    ]
  }
};

// الأقسام الرئيسية
const categoriesList = [
  { id: 'scrubs', titleAr: 'الإسكرابات الطبية', titleEn: 'Medical Scrubs', image: `${BASE}/1__3_-removebg-preview.png` },
  { id: 'coats', titleAr: 'البالطوهات البيضاء', titleEn: 'White Lab Coats', image: `${BASE}/Masked Doctor in White Coat.png` },
];

const CategoryGrid = () => {
  const [activeCategory, setActiveCategory] = useState(null);
  const [currentImageIndex, setCurrentImageIndex] = useState(null);

  // تتبع حالة اللغة لتحديث المكون فوراً عند الضغط على زر الترجمة
  const [isEn, setIsEn] = useState(document.documentElement.dir === "ltr");

  useEffect(() => {
    const handleLangChange = () => {
      setIsEn(document.documentElement.dir === "ltr");
    };
    window.addEventListener('languageChange', handleLangChange);
    return () => window.removeEventListener('languageChange', handleLangChange);
  }, []);

  const handleNext = (e) => {
    e.stopPropagation();
    if (activeCategory) {
      const items = categoryData[activeCategory].items;
      setCurrentImageIndex((prev) => (prev + 1) % items.length);
    }
  };

  const handlePrev = (e) => {
    e.stopPropagation();
    if (activeCategory) {
      const items = categoryData[activeCategory].items;
      setCurrentImageIndex((prev) => (prev - 1 + items.length) % items.length);
    }
  };

  const handleWhatsAppOrder = (productTitle) => {
    const phoneNumber = "201234567890"; // استبدل هذا برقم واتساب الخاص بك
    const message = encodeURIComponent(
      isEn
        ? `Hello Mamy Brand, I would like to inquire and order this product: ${productTitle}`
        : `مرحباً مامي براند، أرغب في الاستفسار وطلب هذا المنتج: ${productTitle}`
    );
    window.open(`https://wa.me/${phoneNumber}?text=${message}`, '_blank');
  };

  return (
    <div
      className="category-section-wrapper"
      style={{
        padding: '80px 5%',
        background: '#0e4670',
        backgroundImage: `linear-gradient(rgba(14, 70, 112, 0.93), rgba(14, 70, 112, 0.93)), url('${BASE}/logo.png')`,
        backgroundRepeat: 'no-repeat',
        backgroundPosition: 'center',
        backgroundSize: '40% auto',
        backgroundAttachment: 'fixed',
        color: '#fff',
        direction: isEn ? 'ltr' : 'rtl',
        position: 'relative'
      }}
    >
      {!activeCategory ? (
        <>
          <div style={{ textAlign: 'center', marginBottom: '50px', position: 'relative', zIndex: 2 }}>
            <h2 style={{ fontSize: '2.5rem', fontWeight: '800', marginBottom: '15px', color: '#fff' }}>
              {isEn ? 'Medical Product Categories' : 'أقسام المنتجات الطبية'}
            </h2>
            <p style={{ color: '#faf8f7', fontSize: '1.1rem' }}>
              {isEn ? 'Choose the appropriate category to browse the latest products and offers' : 'اختر القسم المناسب لاستعراض أحدث المنتجات والعروض'}
            </p>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(260px, 1fr))', gap: '30px', maxWidth: '1200px', margin: '0 auto', position: 'relative', zIndex: 2 }}>
            {categoriesList.map((cat) => (
              <div
                key={cat.id}
                onClick={() => setActiveCategory(cat.id)}
                style={{
                  borderRadius: '20px',
                  overflow: 'hidden',
                  cursor: 'pointer',
                  border: '1px solid rgba(255,255,255,0.08)',
                  transition: 'all 0.3s ease',
                  background: 'rgba(255, 255, 255, 0.03)',
                  backdropFilter: 'blur(5px)'
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.transform = 'translateY(-8px)';
                  e.currentTarget.style.borderColor = 'rgba(235, 241, 236, 0.4)';
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.transform = 'translateY(0)';
                  e.currentTarget.style.borderColor = 'rgba(255,255,255,0.08)';
                }}
              >
                <div style={{ width: '100%', height: '260px', overflow: 'hidden', padding: '15px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <img src={cat.image} alt={isEn ? cat.titleEn : cat.titleAr} style={{ width: '100%', height: '100%', objectFit: 'contain' }} />
                </div>
                <div style={{ padding: '20px', textAlign: 'center' }}>
                  <h3 style={{ fontSize: '1.2rem', color: '#fff', marginBottom: '10px' }}>
                    {isEn ? cat.titleEn : cat.titleAr}
                  </h3>
                  <span style={{ color: '#fafafa', fontSize: '0.9rem', fontWeight: 'bold' }}>
                    {isEn ? 'Browse Products →' : 'تصفح المنتجات ←'}
                  </span>
                </div>
              </div>
            ))}
          </div>
        </>
      ) : (
        <div style={{ maxWidth: '1200px', margin: '0 auto', position: 'relative', zIndex: 2 }}>
          <button
            onClick={() => setActiveCategory(null)}
            style={{
              marginBottom: '30px',
              padding: '10px 20px',
              background: 'rgba(89, 19, 180, 0.1)',
              color: '#00f2fe',
              border: '1px solid rgba(0, 242, 254, 0.3)',
              borderRadius: '12px',
              cursor: 'pointer',
              fontWeight: 'bold',
              display: 'inline-flex',
              alignItems: 'center',
              gap: '8px'
            }}
          >
            {isEn ? '← Back to Main Categories' : '← العودة للأقسام الرئيسية'}
          </button>

          <h2 style={{ fontSize: '2.2rem', fontWeight: '800', marginBottom: '30px', color: '#fafafa' }}>
            {isEn ? categoryData[activeCategory].titleEn : categoryData[activeCategory].titleAr}
          </h2>

          {/* شبكة الصور الصافية بدون كلام أو أزرار أسفلها */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', gap: '30px' }}>
            {categoryData[activeCategory].items.map((product, index) => {
              const productTitle = isEn ? product.titleEn : product.titleAr;
              return (
                <div
                  key={product.id}
                  onClick={() => setCurrentImageIndex(index)}
                  style={{
                    borderRadius: '20px',
                    overflow: 'hidden',
                    cursor: 'zoom-in',
                    transition: 'all 0.3s ease',
                    background: 'rgba(255, 255, 255, 0.03)',
                    backdropFilter: 'blur(5px)',
                    border: '1px solid rgba(255,255,255,0.08)'
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.transform = 'translateY(-6px)';
                    e.currentTarget.style.borderColor = 'rgba(255, 255, 255, 0.4)';
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.transform = 'translateY(0)';
                    e.currentTarget.style.borderColor = 'rgba(255,255,255,0.08)';
                  }}
                >
                  <div style={{ width: '100%', height: '280px', overflow: 'hidden', padding: '15px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                    <img
                      src={product.src}
                      alt={productTitle}
                      style={{ width: '100%', height: '100%', objectFit: 'contain', transition: 'transform 0.4s' }}
                      onMouseEnter={(e) => e.currentTarget.style.transform = 'scale(1.08)'}
                      onMouseLeave={(e) => e.currentTarget.style.transform = 'scale(1)'}
                    />
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* نافذة العرض بكامل الشاشة (Lightbox Modal) مع زر الواتساب وعرض الصور بسلاسة */}
      {currentImageIndex !== null && activeCategory && (
        <div
          onClick={() => setCurrentImageIndex(null)}
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            width: '100vw',
            height: '100vh',
            background: 'rgba(14, 70, 112, 0.95)',
            backdropFilter: 'blur(10px)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 9999,
            padding: '20px'
          }}
        >
          <button
            onClick={() => setCurrentImageIndex(null)}
            style={{
              position: 'absolute',
              top: '30px',
              [isEn ? 'right' : 'left']: '30px',
              background: '#fff',
              color: '#0614d8',
              border: '1px solid rgba(0, 242, 254, 0.4)',
              fontSize: '1.5rem',
              width: '45px',
              height: '45px',
              borderRadius: '50%',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              zIndex: 10000
            }}
          >
            ✕
          </button>

          <button
            onClick={handleNext}
            style={{
              position: 'absolute',
              [isEn ? 'right' : 'left']: '30px',
              background: '#fff',
              color: '#0614d8',
              border: '1px solid rgba(0, 242, 254, 0.4)',
              fontSize: '2rem',
              width: '55px',
              height: '55px',
              borderRadius: '50%',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              zIndex: 10000
            }}
          >
            {isEn ? '›' : '‹'}
          </button>

          <button
            onClick={handlePrev}
            style={{
              position: 'absolute',
              [isEn ? 'left' : 'right']: '30px',
              background: '#fff',
              color: '#0614d8',
              border: '1px solid rgba(0, 242, 254, 0.4)',
              fontSize: '2rem',
              width: '55px',
              height: '55px',
              borderRadius: '50%',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              zIndex: 10000
            }}
          >
            {isEn ? '‹' : '›'}
          </button>

          <div
            onClick={(e) => e.stopPropagation()}
            style={{ textAlign: 'center', maxWidth: '85vw', maxHeight: '85vh', display: 'flex', flexDirection: 'column', alignItems: 'center' }}
          >
            <img
              src={categoryData[activeCategory].items[currentImageIndex].src}
              alt={isEn ? categoryData[activeCategory].items[currentImageIndex].titleEn : categoryData[activeCategory].items[currentImageIndex].titleAr}
              style={{ maxWidth: '100%', maxHeight: '65vh', objectFit: 'contain', borderRadius: '15px', border: '1px solid rgba(0,242,254,0.3)', boxShadow: '0 0 30px rgba(0,242,254,0.2)' }}
            />

            {/* زر الواتساب يظهر هنا عند فتح الصورة للتواصل المباشر */}
            <button
              onClick={() => handleWhatsAppOrder(isEn ? categoryData[activeCategory].items[currentImageIndex].titleEn : categoryData[activeCategory].items[currentImageIndex].titleAr)}
              style={{ marginTop: '20px', padding: '12px 30px', background: '#25D366', color: '#fff', border: 'none', borderRadius: '12px', fontWeight: 'bold', cursor: 'pointer', fontSize: '1.05rem', display: 'flex', alignItems: 'center', gap: '8px', boxShadow: '0 5px 15px rgba(37,211,102,0.4)' }}
            >
              {isEn ? 'Order via WhatsApp' : 'اطلب عبر واتساب'}
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default CategoryGrid;