import React, { useEffect, useRef, useState } from 'react';
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { translations } from '../translations';
import './DoctorShowcase.css';

gsap.registerPlugin(ScrollTrigger);

const BASE = process.env.PUBLIC_URL || "";

const DoctorShowcase = () => {
  const containerRef = useRef(null);
  const doctorImgRef = useRef(null);

  // تتبع حالة اللغة لتحديث المكون فوراً عند الضغط على زر الترجمة
  const [isEn, setIsEn] = useState(document.documentElement.dir === "ltr");

  useEffect(() => {
    const handleLangChange = () => {
      setIsEn(document.documentElement.dir === "ltr");
    };
    window.addEventListener('languageChange', handleLangChange);
    return () => window.removeEventListener('languageChange', handleLangChange);
  }, []);

  const t = translations[isEn ? 'en' : 'ar'];

  useEffect(() => {
    let ctx = gsap.context(() => {
      let tl = gsap.timeline({
        scrollTrigger: {
          trigger: containerRef.current,
          start: 'top top',
          end: '+=500%',
          scrub: 1.5,
          pin: true,
          anticipatePin: 1,
          invalidateOnRefresh: true,
        },
      });

      tl.fromTo(
        doctorImgRef.current,
        { scale: 0.5, opacity: 0, xPercent: -50, yPercent: -50 },
        { scale: 1, opacity: 1, duration: 1, ease: 'power1.out' }
      )
      .to(doctorImgRef.current, { scale: 3, xPercent: -50, yPercent: 70, duration: 2, ease: 'power1.inOut' })
      .to('.info-text.mask', { opacity: 1, y: 0, duration: 0.6 }, '<0.2')
      .to('.info-text.mask', { opacity: 0, y: -20, duration: 0.4 }, '+=1')

      .to(doctorImgRef.current, { scale: 2.5, xPercent: -50, yPercent: -50, duration: 2, ease: 'power1.inOut' })
      .to('.info-text.stethoscope', { opacity: 1, y: 0, duration: 0.6 }, '<0.2')
      .to('.info-text.stethoscope', { opacity: 0, y: -20, duration: 0.4 }, '+=1')

      .to(doctorImgRef.current, { scale: 2.3, xPercent: -35, yPercent: 45, duration: 2, ease: 'power1.inOut' })
      .to('.info-text.scrub', { opacity: 1, y: 0, duration: 0.6 }, '<0.2')
      .to('.info-text.scrub', { opacity: 0, y: -20, duration: 0.4 }, '+=1')

      .to(doctorImgRef.current, { scale: 2.0, xPercent: -55, yPercent: -35, duration: 2, ease: 'power1.inOut' })
      .to('.info-text.coat', { opacity: 1, y: 0, duration: 0.6 }, '<0.2')
      .to('.info-text.coat', { opacity: 0, y: -20, duration: 0.4 }, '+=1')

      .to(doctorImgRef.current, { scale: 1, xPercent: -50, yPercent: -50, duration: 1.5, ease: 'power1.inOut' });

    }, containerRef);

    return () => {
      ScrollTrigger.getAll().forEach(t => t.kill());
      ctx.revert();
    };
  }, []);

  return (
    <section className="doctor-showcase-container" ref={containerRef} style={{ direction: isEn ? 'ltr' : 'rtl' }}>
      <div className="showcase-stage">
        <img
          src={`${BASE}/Masked Doctor in White Coat.png`}
          alt="Medical Showcase"
          className="doctor-image"
          ref={doctorImgRef}
          loading="eager"
        />

        <div className="text-overlay">
          <div className="info-text mask">
            <span className="medical-badge">{t.docBadge1}</span>
            <h2>{t.docTitle1}</h2>
            <p>{t.docDesc1}</p>
          </div>

          <div className="info-text stethoscope">
            <span className="medical-badge">{t.docBadge2}</span>
            <h2>{t.docTitle2}</h2>
            <p>{t.docDesc2}</p>
          </div>

          <div className="info-text scrub">
            <span className="medical-badge">{t.docBadge3}</span>
            <h2>{t.docTitle3}</h2>
            <p>{t.docDesc3}</p>
          </div>

          <div className="info-text coat">
            <span className="medical-badge">{t.docBadge4}</span>
            <h2>{t.docTitle4}</h2>
            <p>{t.docDesc4}</p>
          </div>
        </div>
      </div>
    </section>
  );
};

export default DoctorShowcase;