import React, { useRef, useState, useEffect, Suspense } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { useGLTF, OrbitControls, Center } from '@react-three/drei';
import './Syringe3D.css';

const MODEL_PATH = `${process.env.PUBLIC_URL || ''}/models/Syringe.glb`;

const Model = () => {
  const gltf = useGLTF(MODEL_PATH);
  const modelRef = useRef();

  useFrame((state) => {
    const time = state.clock.getElapsedTime();
    if (modelRef.current) {
      modelRef.current.rotation.y = time * 0.5;
      modelRef.current.rotation.x = Math.sin(time * 0.5) * 0.2;
    }
  });

  return (
    <Center>
      <primitive ref={modelRef} object={gltf.scene} scale={2.2} />
    </Center>
  );
};

useGLTF.preload(MODEL_PATH);

const Syringe3D = () => {
  const [isEn, setIsEn] = useState(document.documentElement.dir === "ltr");

  useEffect(() => {
    const handleLangChange = () => {
      setIsEn(document.documentElement.dir === "ltr");
    };
    window.addEventListener('languageChange', handleLangChange);
    return () => window.removeEventListener('languageChange', handleLangChange);
  }, []);

  return (
    <section className="syringe-3d-section" style={{ direction: isEn ? 'ltr' : 'rtl' }}>
      <div className="syringe-3d-container">

        {/* الجزء النصي */}
        <div className="syringe-content">
          <span className="syringe-badge">
            {isEn ? "3D Technology" : "تكنولوجيا ثلاثية الأبعاد"}
          </span>
          <h2>
            {isEn ? "Explore the Precision of Our Interactive Medical Tools" : "استكشف دقة أدواتنا الطبية التفاعلية"}
          </h2>
          <p>
            {isEn
              ? "A 3D model reflecting the highest standards of precision and sterilization in our medical tools, meticulously designed to meet the needs of major hospitals and clinics with exceptional quality."
              : "نموذج ثلاثي الأبعاد يعكس أعلى معايير الدقة والتعقيم في أدواتنا الطبية، مصمم بعناية فائقة لتلبية احتياجات المستشفيات والعيادات الكبرى بجودة استثنائية."}
          </p>
        </div>

        {/* نموذج السرنجة 3D */}
        <div className="canvas-wrapper-clean">
          <Canvas camera={{ position: [0, 0, 5], fov: 50 }}>
            <ambientLight intensity={1.5} />
            <directionalLight position={[10, 10, 5]} intensity={2} />
            <pointLight position={[-10, -10, -5]} color="#00f2fe" intensity={6} />
            <Suspense fallback={null}>
              <Model />
            </Suspense>
            <OrbitControls enableZoom={false} autoRotate={false} />
          </Canvas>
        </div>

      </div>
    </section>
  );
};

export default Syringe3D;