import React, { useState } from 'react';
import { HashRouter as Router, Routes, Route } from 'react-router-dom';
import Preloader from './components/Preloader';
import Navbar from './components/Navbar';
import DoctorShowcase from './components/DoctorShowcase';
import CategoryGrid from './components/CategoryGrid';
import ScrollToTop from './components/ScrollToTop'; // استدعاء الزر
import BrandAbout from './components/BrandAbout'; // مكون تعريف البراند الطبي
import Footer from './components/Footer'; // استدعاء الفوتر
import Syringe3D from './components/Syringe3D'; // استدعاء مكون الـ 3D
import HalawaSlider from './components/HalawaSlider';
import './App.css';

// الصفحة الرئيسية فقط
function Home() {
  return (
    <>
      <HalawaSlider />
      <DoctorShowcase />
      <CategoryGrid />
      <ScrollToTop />
      <BrandAbout />
      <Syringe3D /> {/* عرض السرنجة الـ 3D التفاعلية */}
      <Footer /> {/* إدراج الفوتر هنا */}
    </>
  );
}

function App() {
  const [loading, setLoading] = useState(true);

  return (
    <Router>
      <div className="App">
        {loading ? (
          <Preloader onFinish={() => setLoading(false)} />
        ) : (
          <>
            <Navbar />
            <Routes>
              <Route path="/" element={<Home />} />
              <Route path="*" element={<Home />} />
            </Routes>
          </>
        )}
      </div>
    </Router>
  );
}

export default App;