import React, { useState, useEffect } from 'react';
import { translations } from '../translations';
import './BrandAbout.css';

const BrandAbout = () => {
  // تتبع حالة اللغة لتحديث المكون فوراً عند الضغط على زر الترجمة
  const [isEn, setIsEn] = useState(document.documentElement.dir === "ltr");

  useEffect(() => {
    const handleLangChange = () => {
      setIsEn(document.documentElement.dir === "ltr");
    };
    window.addEventListener('languageChange', handleLangChange);
    return () => window.removeEventListener('languageChange', handleLangChange);
  }, []);

  const t = translations[isEn ? 'en' : 'ar'];

  const stats = [
    { number: '+500', label: t.stat1Label },
    { number: '100%', label: t.stat2Label },
    { number: '24/7', label: t.stat3Label },
    { number: '100%', label: t.stat4Label },
  ];

  const features = [
    {
      icon: '🩺',
      title: t.feat1Title,
      desc: t.feat1Desc
    },
    {
      icon: '🏥',
      title: t.feat2Title,
      desc: t.feat2Desc
    },
    {
      icon: '🛡️',
      title: t.feat3Title,
      desc: t.feat3Desc
    },
    {
      icon: '⚙️',
      title: t.feat4Title,
      desc: t.feat4Desc
    }
  ];

  return (
    <section className="brand-about-section">
      <div className="brand-about-container">
        
        {/* الجزء العلوي: التعريف بالمنظومة الطبية المتكاملة */}
        <div className="brand-header">
          <span className="brand-badge">{t.aboutBadge}</span>
          <h2>{t.aboutTitle}</h2>
          <p className="brand-description">
            {isEn ? "We are your trusted partner in providing " : "نحن شريكك الموثوق في تقديم "}
            <strong>{t.aboutDescHighlight}</strong>. 
            {isEn ? " We provide hospitals, clinics, and doctors with integrated solutions combining high precision, modern technology, and the highest internationally certified quality and sterilization standards." : " نوفر للمستشفيات، العيادات، والأطباء حلولاً متكاملة تجمع بين الدقة العالية، التكنولوجيا الحديثة، وأعلى معايير الجودة والتعقيم المعتمدة عالمياً."}
          </p>
        </div>

        {/* شبكة المميزات والتجهيزات */}
        <div className="brand-features-grid">
          {features.map((item, index) => (
            <div key={index} className="feature-card">
              <div className="feature-icon">{item.icon}</div>
              <h3>{item.title}</h3>
              <p>{item.desc}</p>
            </div>
          ))}
        </div>

        {/* شريط الإحصائيات والأرقام */}
        <div className="brand-stats-bar">
          {stats.map((stat, idx) => (
            <div key={idx} className="stat-item">
              <span className="stat-number">{stat.number}</span>
              <span className="stat-label">{stat.label}</span>
            </div>
          ))}
        </div>

      </div>
    </section>
  );
};

export default BrandAbout;