import React, { useState, useEffect } from 'react';
import './Footer.css';

const Footer = () => {
  // تتبع حالة اللغة لتحديث المكون فوراً عند الضغط على زر الترجمة
  const [isEn, setIsEn] = useState(document.documentElement.dir === "ltr");

  useEffect(() => {
    const handleLangChange = () => {
      setIsEn(document.documentElement.dir === "ltr");
    };
    window.addEventListener('languageChange', handleLangChange);
    return () => window.removeEventListener('languageChange', handleLangChange);
  }, []);

  const handleWhatsAppClick = () => {
    const phoneNumber = "201234567890"; // استبدل برقم الواتساب الخاص بك
    const message = encodeURIComponent(
      isEn 
        ? "Hello, I would like to inquire about medical devices and supplies."
        : "مرحباً، أرغب في الاستفسار عن الأجهزة والمستلزمات الطبية."
    );
    window.open(`https://wa.me/${phoneNumber}?text=${message}`, '_blank');
  };

  return (
    <footer className="medical-footer" style={{ direction: isEn ? 'ltr' : 'rtl' }}>
      <div className="footer-container">
        
        {/* العمود الأول: الهوية والنبذة */}
        <div className="footer-col brand-col">
          <div className="footer-logo">
            <span className="logo-icon">🩺</span>
            <h3>{isEn ? " MEDI Brand" : " ميدي"}</h3>
          </div>
          <p className="footer-about">
            {isEn 
              ? "Your integrated system for equipping hospitals, clinics, and doctors with the latest certified medical devices and world-class quality tools."
              : "منظومتك المتكاملة لتجهيز المستشفيات، العيادات، والأطباء بأحدث الأجهزة والأدوات الطبية المعتمدة ذات الجودة العالمية."}
          </p>
          <div className="social-links">
            <a href="#facebook" aria-label="Facebook">🌐</a>
            <a href="#instagram" aria-label="Instagram">📸</a>
            <a href="#linkedin" aria-label="LinkedIn">💼</a>
          </div>
        </div>

        {/* العمود الثاني: أقسام المنتجات */}
        <div className="footer-col">
          <h4 className="footer-title">{isEn ? "Medical Departments" : "الأقسام الطبية"}</h4>
          <ul className="footer-links">
            <li><a href="#scrubs">{isEn ? "Scrubs & Medical Wear" : "الإسكرابات والزي الطبي"}</a></li>
            <li><a href="#coats">{isEn ? "White Lab Coats" : "البالطوهات البيضاء"}</a></li>
            <li><a href="#stethoscopes">{isEn ? "Stethoscopes & Diagnostic Tools" : "السماعات وأدوات التشخيص"}</a></li>
            <li><a href="#protection">{isEn ? "Masks & Protection Gear" : "الكمامات ومعدات الحماية"}</a></li>
            <li><a href="#devices">{isEn ? "Devices & Clinics" : "الأجهزة والعيادات"}</a></li>
          </ul>
        </div>

        {/* العمود الثالث: الدعم والخدمات */}
        <div className="footer-col">
          <h4 className="footer-title">{isEn ? "Services & Warranty" : "الخدمات والضمان"}</h4>
          <ul className="footer-links">
            <li><a href="#warranty">{isEn ? "Warranty & Spare Parts" : "الضمان وتوافر قطع الغيار"}</a></li>
            <li><a href="#maintenance">{isEn ? "Certified Maintenance Services" : "خدمات الصيانة المعتمدة"}</a></li>
            <li><a href="#sterilization">{isEn ? "Sterilization & Packaging Policy" : "سياسة التعقيم والتغليف"}</a></li>
            <li><a href="#shipping">{isEn ? "Express Shipping to All Governorates" : "الشحن السريع للمحافظات"}</a></li>
          </ul>
        </div>

        {/* العمود الرابع: الاتصال والطلب السريع */}
        <div className="footer-col contact-col">
          <h4 className="footer-title">{isEn ? "Contact Us" : "تواصل معنا"}</h4>
          <p className="contact-item">{isEn ? "📍 Cairo / Alexandria - All Governorates" : "📍 القاهرة / الإسكندرية - جميع المحافظات"}</p>
          <p className="contact-item">📞 01234567890</p>
          <p className="contact-item">✉️ info@medicalbrand.com</p>
          
          <button className="footer-wa-btn" onClick={handleWhatsAppClick}>
            {isEn ? "Contact via WhatsApp" : "تواصل عبر واتساب"}
          </button>
        </div>

      </div>

      {/* شريط حقوق الملكية السفلي */}
      <div className="footer-bottom">
        <div className="footer-bottom-container">
          <p>
            {isEn 
              ? `© ${new Date().getFullYear()} All Rights Reserved - Integrated Medical System.`
              : `© ${new Date().getFullYear()} جميع الحقوق محفوظة - المنظومة الطبية المتكاملة.`}
          </p>
          <p className="tech-credit">
            {isEn ? "Designed & Developed by " : "تصميم وتطوير بواسطة "} 
            <span>Ziad Hamada</span>
          </p>
        </div>
      </div>
    </footer>
  );
};

export default Footer;