import React, { useState, useEffect } from 'react';
import { translations } from '../translations';
import './Navbar.css';

const Navbar = () => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [lang, setLang] = useState('en');

  useEffect(() => {
    document.documentElement.dir = lang === 'ar' ? 'rtl' : 'ltr';
    document.documentElement.lang = lang;
    window.dispatchEvent(new Event('languageChange'));
  }, [lang]);

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen);
  };

  const toggleLanguage = () => {
    setLang((prev) => (prev === 'ar' ? 'en' : 'ar'));
  };

  const t = translations[lang];

  return (
    <header className="navbar-wrapper">
      {/* هالة النيون خلف الكبسولة */}
      <div className="pill-glow-underlay"></div>

      {/* الكبسولة الموحدة */}
      <nav className="pill-capsule" style={{ direction: lang === 'ar' ? 'rtl' : 'ltr' }}>

        {/* الشعار واللوجو كصورة */}
        <a href="#home" className="logo-container" aria-label="MEDI Supplies">
          <img
            src={`${process.env.PUBLIC_URL}/Medi supplies-06.png`}
            alt="MEDI Supplies Logo"
            className="navbar-logo-img"
          />
        </a>

        {/* مجموعة الروابط وزر اللغة والقائمة */}
        <div className={`nav-content-right ${isMenuOpen ? 'active' : ''}`}>
          <ul className="nav-links">
            <li><a href="#home" onClick={() => setIsMenuOpen(false)}>{t.home}</a></li>
            <li><a href="#products" onClick={() => setIsMenuOpen(false)}>{t.products}</a></li>
            <li><a href="#about" onClick={() => setIsMenuOpen(false)}>{t.about}</a></li>
            <li><a href="#contact" onClick={() => setIsMenuOpen(false)}>{t.contact}</a></li>
          </ul>

          {/* زر تغيير اللغة جنب الروابط */}
          <button className="lang-toggle-btn" onClick={toggleLanguage} aria-label="Toggle Language">
            🌐 {t.langToggle}
          </button>
        </div>

        {/* زر الهامبرغر للموبايل */}
        <button className="mobile-toggle" onClick={toggleMenu} aria-label="Toggle Navigation">
          <span className={`toggle-bar ${isMenuOpen ? 'open' : ''}`}></span>
          <span className={`toggle-bar ${isMenuOpen ? 'open' : ''}`}></span>
          <span className={`toggle-bar ${isMenuOpen ? 'open' : ''}`}></span>
        </button>

      </nav>
    </header>
  );
};

export default Navbar;