import React, { useState, useEffect } from 'react';
import './ScrollToTop.css';

const ScrollToTop = () => {
  const [isVisible, setIsVisible] = useState(false);
  const [isInjecting, setIsInjecting] = useState(false);

  useEffect(() => {
    const toggleVisibility = () => {
      if (window.scrollY > 300) {
        setIsVisible(true);
      } else {
        setIsVisible(false);
      }
    };

    window.addEventListener('scroll', toggleVisibility);
    return () => window.removeEventListener('scroll', toggleVisibility);
  }, []);

  const handleClick = () => {
    // تفعيل حركة الحقنة والقطرات
    setIsInjecting(true);

    // صعود الصفحة للأعلى بعد بدء الحركة بقليل
    setTimeout(() => {
      window.scrollTo({
        top: 0,
        behavior: 'smooth',
      });
    }, 200);

    // إنهاء حركة الحقنة وإعادة ضبط الحالة
    setTimeout(() => {
      setIsInjecting(false);
    }, 800);
  };

  return (
    <>
      {isVisible && (
        <div className="scroll-to-top-wrapper">
          <button 
            className={`scroll-to-top-btn ${isInjecting ? 'injecting' : ''}`} 
            onClick={handleClick} 
            title="حقنة الصعود للأعلى"
          >
            {/* أيقونة الحقنة الطبية */}
            <svg 
              width="28" 
              height="28" 
              viewBox="0 0 24 24" 
              fill="currentColor"
            >
              <path d="M19.707 4.293a1 1 0 0 0-1.414 0l-1.42 1.42-1.414-1.414 1.414-1.414a1 1 0 1 0-1.414-1.414l-1.414 1.414-1.414-1.414a1 1 0 0 0-1.414 1.414l1.414 1.414-8.879 8.879a3 3 0 0 0 0 4.242l1.414 1.414L2.293 21.707a1 1 0 0 0 1.414 1.414l3.121-3.121 1.414 1.414a3 3 0 0 0 4.242 0l8.879-8.879 1.414 1.414a1 1 0 0 0 1.414-1.414l-1.414-1.414 1.414-1.414a1 1 0 0 0 0-1.414zM11.121 17.121a1 1 0 0 1-1.414 0l-2.828-2.828a1 1 0 0 1 0-1.414L14.5 5.272l4.242 4.242-7.621 7.607z"/>
            </svg>
          </button>

          {/* قطرات المياه/المحلول النيون عند الضغط */}
          {isInjecting && (
            <div className="drops-container">
              <span className="drop drop-1"></span>
              <span className="drop drop-2"></span>
              <span className="drop drop-3"></span>
            </div>
          )}
        </div>
      )}
    </>
  );
};

export default ScrollToTop;