import React, { useEffect, useState } from 'react';

const Preloader = ({ onFinish }) => {
  const [stage, setStage] = useState('ecg'); // 'ecg' -> 'logo' -> 'exit'

  useEffect(() => {
    const logoTimer = setTimeout(() => {
      setStage('logo');
    }, 2000);

    const zoomTimer = setTimeout(() => {
      setStage('exit');
    }, 3300);

    const finishTimer = setTimeout(() => {
      if (onFinish) {
        onFinish();
      }
    }, 4100);

    return () => {
      clearTimeout(logoTimer);
      clearTimeout(zoomTimer);
      clearTimeout(finishTimer);
    };
  }, [onFinish]);

  return (
    <div
      style={{
        position: 'fixed',
        inset: 0,
        width: '100vw',
        height: '100vh',
        backgroundColor: '#071329',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        zIndex: 99999,
        opacity: stage === 'exit' ? 0 : 1,
        pointerEvents: stage === 'exit' ? 'none' : 'auto',
        transition: 'opacity 0.6s ease',
        direction: 'ltr',
        boxSizing: 'border-box',
      }}
    >
      <style>{`
        @keyframes ecgDraw {
          0% {
            stroke-dashoffset: 900;
          }
          100% {
            stroke-dashoffset: 0;
          }
        }
        @keyframes logoAppear {
          0% {
            opacity: 0;
            transform: scale(0.75);
          }
          100% {
            opacity: 1;
            transform: scale(1);
          }
        }
        @keyframes logoExpandExit {
          0% {
            opacity: 1;
            transform: scale(1);
          }
          100% {
            opacity: 0;
            transform: scale(2.4);
          }
        }
      `}</style>

      {stage === 'ecg' && (
        <div
          style={{
            width: '100%',
            maxWidth: '520px',
            margin: '0 auto',
            padding: '0 20px',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            boxSizing: 'border-box',
          }}
        >
          <svg
            viewBox="0 0 500 150"
            preserveAspectRatio="xMidYMid meet"
            style={{
              width: '100%',
              maxWidth: '500px',
              height: 'auto',
              display: 'block',
              margin: '0 auto',
            }}
          >
            <path
              d="M 0 75 Q 40 75, 80 75 T 160 75 L 180 30 L 195 120 L 210 10 L 230 135 L 245 60 L 260 75 T 340 75 T 500 75"
              fill="none"
              stroke="rgba(0, 242, 254, 0.2)"
              strokeWidth="4"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
            <path
              d="M 0 75 Q 40 75, 80 75 T 160 75 L 180 30 L 195 120 L 210 10 L 230 135 L 245 60 L 260 75 T 340 75 T 500 75"
              fill="none"
              stroke="#00f2fe"
              strokeWidth="4"
              strokeLinecap="round"
              strokeLinejoin="round"
              style={{
                strokeDasharray: 900,
                strokeDashoffset: 900,
                animation: 'ecgDraw 1.9s ease-in-out forwards',
                filter: 'drop-shadow(0 0 10px #00f2fe)',
              }}
            />
          </svg>
        </div>
      )}

      {(stage === 'logo' || stage === 'exit') && (
        <div
          style={{
            width: '100%',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            padding: '0 20px',
            boxSizing: 'border-box',
            animation:
              stage === 'exit'
                ? 'logoExpandExit 0.75s ease-in forwards'
                : 'logoAppear 0.55s ease-out forwards',
          }}
        >
          <img
            src={`${process.env.PUBLIC_URL}/Medi supplies-06.png`}
            alt="MEDI Supplies Logo"
            style={{
              maxWidth: '240px',
              width: '70%',
              height: 'auto',
              display: 'block',
              margin: '0 auto',
            }}
          />
        </div>
      )}
    </div>
  );
};

export default Preloader;